log.info(tw.local.sqlStats);"],"nodeVisualInfo":[{"width":95,"x":433,"y":57,"declaredType":"TNodeVisualInfo","height":70}],"preAssignmentScript":["log.info("<<Update Cancelled Transactions>>");
log.info("<<transactions>>");

log.info(tw.local.transactions)

log.info("<<lastRequestTransactions>>");
log.info(tw.local.lastRequestTransactions)

log.info("<<status>>");
log.info(tw.local.status);"]},"name":"SQL UPDATE TRANSACTION","isForCompensation":false,"completionQuantity":1,"declaredType":"scriptTask","id":"39bf4268-d1c0-4a11-8305-9cf4e31a9a6d","scriptFormat":"text/x-javascript","script":{"content":["function addSQLParameter(value) {
	if (value === null || value === undefined) {
		value = "";
	} else if (typeof value === "string") {
		value = value || "";
	} else if (typeof value === "number") {
		value = value || 0;
	} else if (typeof value === "boolean") {
		value = value ? "1" : "0";
	}
	var parameter = new tw.object.SQLParameter();
	parameter.value = value;
	parameter.mode = "IN";
	return parameter;
}

function sameDate(dateStr1, dateStr2) {
	var d1 = new Date(dateStr1);
	var d2 = new Date(dateStr2);

	return d1.getDate() === d2.getDate() && d1.getMonth() === d2.getMonth() && d1.getFullYear() === d2.getFullYear();
}

tw.local.sqlStats = new tw.object.listOf.SQLStatement();
var index = 0;

if (tw.local.status == "" + tw.epv.Status.Canceled) {
	for (var i = 0; i < tw.local.transactions.listLength; i++) {
		//lock
		tw.local.sqlStats[index] = new tw.object.SQLStatement();
		tw.local.sqlStats[index].sql = "SELECT * FROM " + tw.env.LKP_DB_Schema + ".ODC_FCTRANSACTION WHERE ID = ? FOR UPDATE";
		tw.local.sqlStats[index].parameters = new tw.object.listOf.SQLParameter();
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactionID[i]));
		index++;

		//calculate by getting latest amount linked and update

		tw.local.sqlStats[index] = new tw.object.SQLStatement();
		tw.local.sqlStats[index].parameters = new tw.object.listOf.SQLParameter();

		//fixed parameteres
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactions[i].amountAllocatedForCurrencyRequest));
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactions[i].allocatedAmountInRequestCurrency));
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactions[i].referenceNumber));
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactions[i].postingDate));

		//for new added transactions, remove the added amount
		if (tw.local.transactions[i].changeOperation == "N") {
			tw.local.sqlStats[index].sql = "UPDATE " + tw.env.LKP_DB_Schema + ".ODC_FCTRANSACTION SET AMOUNTFORCURRENTREQ = ?, AMOUNTINREQCURRENCY = ? , " + "AMOUNTLINKEDINBPM = (SELECT AMOUNTLINKEDINBPM FROM " + tw.env.LKP_DB_Schema + ".ODC_FCTRANSACTION WHERE REFERENCENO = ? AND CAST(POSTINGDATE AS DATE) = CAST(? AS DATE)) - ? " + "WHERE ID = ?";

			tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactions[i].amountAllocatedForCurrencyRequest));
		} else {
			for (var x = 0; x < tw.local.lastRequestTransactions.length; x++) {
				if (tw.local.transactions[i].referenceNumber === tw.local.lastRequestTransactions[x].referenceNumber && sameDate(tw.local.transactions[i].postingDate, tw.local.lastRequestTransactions[x].postingDate)) {
					// for changed transactions replace the new added amount with the old amount
					if (tw.local.transactions[i].changeOperation == "C") {
						tw.local.sqlStats[index].sql = "UPDATE " + tw.env.LKP_DB_Schema + ".ODC_FCTRANSACTION SET AMOUNTFORCURRENTREQ = ?, AMOUNTINREQCURRENCY = ?, " + "AMOUNTLINKEDINBPM = (SELECT AMOUNTLINKEDINBPM FROM " + tw.env.LKP_DB_Schema + ".ODC_FCTRANSACTION WHERE REFERENCENO = ? AND CAST(POSTINGDATE AS DATE) = CAST(? AS DATE)) - ? + ? " + "WHERE ID = ?";

						tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactions[i].amountAllocatedForCurrencyRequest));
						tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.lastRequestTransactions[x].amountAllocatedForCurrencyRequest));

						break;
					}

					//for deleted transactions add again the deleted amount
					else if (tw.local.transactions[i].changeOperation == "D") {
						tw.local.sqlStats[index].sql = "UPDATE " + tw.env.LKP_DB_Schema + ".ODC_FCTRANSACTION SET AMOUNTFORCURRENTREQ = ?, AMOUNTINREQCURRENCY = ?, " + "AMOUNTLINKEDINBPM = (SELECT AMOUNTLINKEDINBPM FROM " + tw.env.LKP_DB_Schema + ".ODC_FCTRANSACTION WHERE REFERENCENO = ? AND CAST(POSTINGDATE AS DATE) = CAST(? AS DATE)) + ? " + "WHERE ID = ?";

						tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.lastRequestTransactions[x].allocatedAmountInRequestCurrency));

						break;
					} else {
						tw.local.sqlStats[index].sql = "SELECT AMOUNTFORCURRENTREQ FROM " + tw.env.LKP_DB_Schema + ".ODC_FCTRANSACTION WHERE AMOUNTFORCURRENTREQ = ? AND AMOUNTINREQCURRENCY = ? AND REFERENCENO = ? AND CAST(POSTINGDATE AS DATE) = CAST(? AS DATE) AND ID = ?";
					}
				}
			}
		}

		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactionID[i]));
		index++;

		//update ODC_SELECTEDTRANSACTIONS table
		log.info("Update selected");
		tw.local.sqlStats[index] = new tw.object.SQLStatement();
		tw.local.sqlStats[index].sql = "UPDATE " + tw.env.LKP_DB_Schema + ".ODC_SELECTEDTRANSACTIONS SET ISDELETED = 'Yes' " + "WHERE REQUESTID = ? AND TRANSACTIONID = ?";
		tw.local.sqlStats[index].parameters = new tw.object.listOf.SQLParameter();
		//request id same for all transactions in cancelled case
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactions[i].requestID));
		log.info("UPDATE queyr REQUEST ID : " + tw.local.transactions[i].requestID);
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactionID[i]));
		log.info("UPDATE query ID : " + tw.local.transactionID[i]);
		index++;
	}
}

//reversal
else {
	log.info("<<reversal>>");
	log.info(tw.local.transactions);
	log.info(tw.local.reverseIDs);

	for (var i = 0; i < tw.local.transactions.listLength; i++) {
		//lock
		tw.local.sqlStats[index] = new tw.object.SQLStatement();
		tw.local.sqlStats[index].sql = "SELECT ID, ACCOUNTNO, REFERENCENO, POSTINGDATE, VALUEDATE, TRANSACTIONAMOUNT, AMOUNTLINKEDINBPM, AMOUNTFORCURRENTREQ, AMOUNTINREQCURRENCY FROM " + tw.env.LKP_DB_Schema + ".ODC_FCTRANSACTION WHERE ID = ? FOR UPDATE";
		tw.local.sqlStats[index].parameters = new tw.object.listOf.SQLParameter();
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactionID[i]));
		index++;

		//calculate by getting latest amount linked and update

		tw.local.sqlStats[index] = new tw.object.SQLStatement();

		tw.local.sqlStats[index].sql =
			"UPDATE " +
			tw.env.LKP_DB_Schema +
			".ODC_FCTRANSACTION SET AMOUNTFORCURRENTREQ = ?, AMOUNTINREQCURRENCY = ? , " +
			"AMOUNTLINKEDINBPM = (SELECT AMOUNTLINKEDINBPM FROM " +
			tw.env.LKP_DB_Schema +
			".ODC_FCTRANSACTION WHERE REFERENCENO = ? AND CAST(POSTINGDATE AS DATE) = CAST(? AS DATE)) - " +
			"(SELECT AMOUNTINCURRENTREQ FROM " +
			tw.env.LKP_DB_Schema +
			".ODC_SELECTEDTRANSACTIONS WHERE ISDELETED <> 'Yes' AND REQUESTID = ? AND TRANSACTIONID = ? ORDER BY ID DESC FETCH FIRST 1 ROW ONLY) " +
			"WHERE ID = ?";

		tw.local.sqlStats[index].parameters = new tw.object.listOf.SQLParameter();

		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactions[i].amountAllocatedForCurrencyRequest));
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactions[i].allocatedAmountInRequestCurrency));
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactions[i].referenceNumber));
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactions[i].postingDate));
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.latestID));
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactionID[i]));
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactionID[i]));
		index++;
	}
	//
	for (var x = 0; x < tw.local.reverseIDs.listLength; x++) {
		tw.local.sqlStats[index] = new tw.object.SQLStatement();
		tw.local.sqlStats[index].sql = "UPDATE " + tw.env.LKP_DB_Schema + ".ODC_SELECTEDTRANSACTIONS SET ISDELETED = 'Yes' " + "WHERE REQUESTID = ?";
		tw.local.sqlStats[index].parameters = new tw.object.listOf.SQLParameter();
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.reverseIDs[x]));
		index++;
	}
}
"]}},{"startQuantity":1,"outgoing":["90e6c969-233a-4232-bf82-56222b4bbbb7"],"incoming":["b5ebbe18-77b4-4c8d-99d1-be316e1234be"],"extensionElements":{"postAssignmentScript":["tw.local.isSuccessful = true;
	

