],"dataOutput":[{"itemSubjectRef":"itm.19e8dc33-1100-46be-89a6-36c9040f7b3e","name":"error","isCollection":false,"id":"5824cbee-c563-4aa6-b9b6-c98141e941e9"}],"eventDefinition":[{"extensionElements":{"errorEventSettings":[{"catchAll":true,"declaredType":"com.ibm.bpmsdk.model.bpmn20.ibmwleext.TErrorEventSettings"}]},"declaredType":"errorEventDefinition","id":"8e74ab9f-bfcd-468a-a040-f447deffd2ac","otherAttributes":{"eventImplId":"e68c1d0c-662e-455c-841e-7d89ac034f1c"}}],"attachedToRef":"86773b5f-1f6a-4fa5-a300-f3de0625bba7","extensionElements":{"nodeVisualInfo":[{"width":24,"x":604,"y":115,"declaredType":"TNodeVisualInfo","height":24}]},"cancelActivity":true,"name":"Error1","declaredType":"boundaryEvent","id":"e28401dd-5fe4-40ce-8def-f18a74c7249e","outputSet":{}},{"targetRef":"d89cbd9d-a369-4742-bf9a-d471c5d86861","extensionElements":{"linkVisualInfo":[{"sourcePortLocation":"bottomCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":false,"showLabel":false}]},"name":"To Exception Handling","declaredType":"sequenceFlow","id":"384e4aef-e0c9-4b5e-8ea6-8439c9034124","sourceRef":"e28401dd-5fe4-40ce-8def-f18a74c7249e"},{"itemSubjectRef":"itm.12.3990d8b4-983d-4250-bd06-3600f527fed0","name":"sqlStats","isCollection":true,"declaredType":"dataObject","id":"2056.47312291-6783-4875-b518-e0c7d21e3afb"},{"startQuantity":1,"outgoing":["b6e92d23-87e5-45de-bdd8-bfdd142c1a16"],"incoming":["384e4aef-e0c9-4b5e-8ea6-8439c9034124"],"extensionElements":{"nodeVisualInfo":[{"color":"#AAAAAA","width":95,"x":726,"y":163,"declaredType":"TNodeVisualInfo","height":70}]},"name":"Exception Handling","isForCompensation":false,"completionQuantity":1,"declaredType":"scriptTask","id":"d89cbd9d-a369-4742-bf9a-d471c5d86861","scriptFormat":"text/x-javascript","script":{"content":["if (!!tw.system.error) {
 var errorText = tw.system.error;
 log.info("Process Instance ID: " + tw.system.currentProcessInstanceID +
 " - Service Name: " + tw.system.serviceFlow.name +
 " - Error: " + tw.system.error);

 var errorM = String(tw.system.error.xpath("/error/message").item(0).getText());
 

 // Detect DB2 SQL error Locking
// if (errorM.includes("SQLCODE=-911") || errorM.includes("SQLCODE=-913")) {
// tw.local.LockedErrorMSG = "Another user is currently working on this transaction. Please try again in a few moments.";
// } 

 	 tw.local.errorMSG = "Error occurred in service (" + tw.system.serviceFlow.name + "). Please contact the administrator.";
// else {
// }
}

else {
 tw.local.errorMSG = "An unexpected error occurred in service (" + tw.system.serviceFlow.name + "). Please contact the administrator.";

}

